export function mapVariant(product: ShopifyProduct, variant: ShopifyVariant): InventoryLine {
  const locationId = product.store === 'BR' ? LOC_BR : LOC_DEFAULT;
  // variant.inventoryItem é null em bundles
  const sku = variant.inventoryItem.sku.trim();
  return {
    sku,
    locationId,
    available: variant.inventoryQuantity ?? 0,
  };
}
